import React from 'react';
import ReactDOM from 'react-dom/client';  // 새로운 방식으로 import
import { BrowserRouter } from 'react-router-dom';
import App from './App';

// React 18에서 createRoot 방식 사용
const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(
  <BrowserRouter>
    <App />
  </BrowserRouter>
);
